INSERT OR IGNORE INTO maqams (id, name, malayalam_name, location, city, country, region, category, era, description, significance, best_time_to_visit, source_url, cover_image, address_detail, visiting_hours, facilities, how_to_reach, contact_info, history, architecture, created_from_request_id, status, created_at, updated_at) VALUES ('mampuram', 'Mampuram Maqam', 'മമ്പുറം മഖാം', 'Mampuram Juma Masjid', 'Tirurangadi, Malappuram', 'India', 'kerala', 'scholar', '19th century', 'Resting place of Sayyid Alavi Thangal and Sayyid Fazal Pookoya Thangal, revered scholars and reformers of Malabar.', 'Center of spiritual learning and historic resistance during colonial Malabar.', 'Rabi al-Awwal Uroos', 'https://en.wikipedia.org/wiki/Mamburam_Thangal', '/assets/maqam-mampuram-B9iQQ0Wc.jpg', 'Mampuram Juma Masjid, Tirurangadi, Malappuram District, Kerala 676102', '[{"label":"Daily Dars","hours":"Fajr to Isha"},{"label":"Ziyarath access","hours":"Open 24 hours"},{"label":"Office hours","hours":"9:00 AM – 5:00 PM"}]', '["Ablution area","Restroom","Parking","Guest house","Free drinking water"]', '[{"mode":"By Air","details":"Calicut International Airport (CCJ) — 22 km away. Taxis available."},{"mode":"By Train","details":"Tirurangadi Railway Station — 2 km from the maqam. Auto-rickshaws frequent."},{"mode":"By Road","details":"NH 66 passes through Tirurangadi. Local buses from Malappuram and Calicut."}]', '{"phone":"+91-494-xxx-xxxx"}', 'Sayyid Alavi Thangal arrived in Malabar from Yemen in 1798 and established the Mampuram Juma Masjid as a center of Islamic learning and spiritual guidance. The maqam became a symbol of resistance during British colonial rule.', 'Traditional Kerala-Islamic architecture with laterite stone walls, teak wood ceilings, and ornate mihrab. The tomb chamber is adorned with green velvet and brass railings.', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO maqams (id, name, malayalam_name, location, city, country, region, category, era, description, significance, best_time_to_visit, source_url, cover_image, address_detail, visiting_hours, facilities, how_to_reach, contact_info, history, architecture, created_from_request_id, status, created_at, updated_at) VALUES ('kondotty', 'Kondotty Khubba', 'കൊണ്ടോട്ടി ഖുബ്ബ', 'Kondotty Thakkiya', 'Kondotty, Malappuram', 'India', 'kerala', 'sufi', '18th century', 'Shrine of Muhammad Shah Tangal, founder of the Kondotty Sufi tradition in Kerala.', 'Annual Nercha draws devotees from across South India.', 'Rajab Nercha', NULL, '/assets/maqam-kondotty-D12iMTTK.jpg', 'Kondotty Thakkiya, Kondotty, Malappuram District, Kerala 673638', '[{"label":"Dargah open","hours":"5:00 AM – 10:00 PM"},{"label":"Special Qawwali","hours":"Every Thursday 7:00 PM"}]', '["Parking","Restroom","Ablution area","Shops for offerings"]', '[{"mode":"By Air","details":"Calicut International Airport (CCJ) — 18 km away."},{"mode":"By Train","details":"Feroke Railway Station — 12 km. Kondotty has local bus connectivity."},{"mode":"By Road","details":"Well connected via NH 966. Buses from Malappuram and Calicut every 30 minutes."}]', NULL, 'Muhammad Shah Tangal, a Qadiri mystic from Yemen, established the Kondotty Thakkiya in the early 18th century. The shrine became the spiritual center of the Kondotty Sufi order, spreading across northern Kerala.', 'Distinctive two-storied structure with a large prayer hall and the tomb chamber on the ground floor. The exterior features intricate wood carvings typical of Malabar mosque architecture.', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO maqams (id, name, malayalam_name, location, city, country, region, category, era, description, significance, best_time_to_visit, source_url, cover_image, address_detail, visiting_hours, facilities, how_to_reach, contact_info, history, architecture, created_from_request_id, status, created_at, updated_at) VALUES ('ponnani', 'Ponnani Valiya Juma Masjid Maqbara', 'പൊന്നാനി മഖ്ബറ', 'Ponnani Valiya Juma Masjid', 'Ponnani, Malappuram', 'India', 'kerala', 'scholar', '16th century', 'Burial site of Makhdoom scholars including Zainuddin Makhdoom I & II, the spiritual axis of Malabar.', 'Known as the Mecca of Malabar for centuries of Islamic scholarship.', NULL, NULL, NULL, 'Ponnani Valiya Juma Masjid, Ponnani, Malappuram District, Kerala 679586', '[{"label":"Masjid open","hours":"Fajr to Isha prayers"},{"label":"Maqbara access","hours":"After Fajr to before Maghrib"}]', '["Ablution area","Library","Restroom","Parking"]', '[{"mode":"By Train","details":"Ponnani Railway Station — 3 km. Or Tirur Jn — 20 km."},{"mode":"By Road","details":"Buses from Malappuram, Thrissur, and Kochi. NH 66 connects to Ponnani road."}]', NULL, 'Ponnani has been a center of Islamic learning since the 7th century AH. Zainuddin Makhdoom I authored the famous Tuhfat al-Mujahidin here, chronicling the struggle against Portuguese colonialism.', 'One of the oldest mosques in Kerala with massive laterite walls, teak pillars, and a traditional Kerala-style roof. The maqbara is located in a serene courtyard behind the main prayer hall.', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO maqams (id, name, malayalam_name, location, city, country, region, category, era, description, significance, best_time_to_visit, source_url, cover_image, address_detail, visiting_hours, facilities, how_to_reach, contact_info, history, architecture, created_from_request_id, status, created_at, updated_at) VALUES ('beemapally', 'Beemapally Dargah', 'ബീമാപള്ളി ദർഗ', 'Beemapally Mosque', 'Thiruvananthapuram', 'India', 'kerala', 'sufi', 'Medieval', 'Dargah of Beema Beevi, a revered woman saint from Arabia who settled in Kerala.', NULL, 'Annual Uroos in Jumada al-Akhir', NULL, NULL, 'Beemapally Dargah, Thiruvananthapuram, Kerala 695008', '[{"label":"Dargah open","hours":"5:30 AM – 9:00 PM"}]', '["Ablution area","Restroom","Parking","Shops for offerings"]', '[{"mode":"By Air","details":"Thiruvananthapuram International Airport (TRV) — 5 km away."},{"mode":"By Train","details":"Thiruvananthapuram Central — 7 km. Local buses and auto-rickshaws available."}]', NULL, 'Beema Beevi is believed to have arrived from Arabia with her son Sayyid Hasan. The dargah is one of the few major shrines in Kerala dedicated to a woman saint, attracting devotees across religious boundaries.', 'The tomb is covered with green silk and housed in a small but beautifully maintained chamber. The compound includes a mosque and a large open area for festival gatherings.', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO maqams (id, name, malayalam_name, location, city, country, region, category, era, description, significance, best_time_to_visit, source_url, cover_image, address_detail, visiting_hours, facilities, how_to_reach, contact_info, history, architecture, created_from_request_id, status, created_at, updated_at) VALUES ('madavoor', 'Madavoor C.M. Maqam Sharif', 'മടവൂർ സി.എം. മഖാം ശരീഫ്', 'Madavoor C.M. Center', 'Madavoor, Kozhikode', 'India', 'kerala', 'sufi', '20th century', 'Resting place of Sayyid Muhammad Mouladaveela C.M. Valiyullah, one of the most beloved Ba''alawi spiritual masters of modern Kerala, renowned for his miracles (karamat) and compassionate guidance.', 'A major spiritual centre in North Malabar drawing thousands of seekers for collective Thasbeeh prayers, Haddad Ratheeb recitations, and community harmony gatherings.', 'Annual Uroos in Rabi al-Thani', NULL, NULL, 'Madavoor C.M. Maqam Sharif, Madavoor, Kozhikode District, Kerala', '[{"label":"Maqam open","hours":"Open 24 hours"},{"label":"Ziyarath access","hours":"After Fajr to Isha"}]', '["Ablution area","Restroom","Parking","Guest house","Free community meals during Uroos"]', '[{"mode":"By Air","details":"Calicut International Airport (CCJ) — 40 km away. Taxis and pre-paid cabs available."},{"mode":"By Train","details":"Kozhikode Railway Station — 22 km. Auto-rickshaws and buses connect to Madavoor."},{"mode":"By Road","details":"Connected via NH 66 and local roads from Kozhikode. Regular KSRTC and private buses available."}]', '{"phone":"+91 495 285 6200"}', 'Sayyid Muhammad Mouladaveela C.M. Valiyullah was one of the most celebrated Ba''alawi spiritual masters of 20th-century Kerala. Known for his deep piety, miraculous interventions (karamat), and unwavering service to people of all backgrounds, he became a beacon of spiritual succour across North Malabar. The maqam was established at his resting place and has since become a major pilgrimage destination.', 'The maqam features a traditional Kerala-Islamic design with a green-domed tomb chamber, marble flooring, and ornamental brass railings. The surrounding compound includes a spacious prayer hall and covered areas for community gatherings during the annual Uroos.', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO maqams (id, name, malayalam_name, location, city, country, region, category, era, description, significance, best_time_to_visit, source_url, cover_image, address_detail, visiting_hours, facilities, how_to_reach, contact_info, history, architecture, created_from_request_id, status, created_at, updated_at) VALUES ('ajmer', 'Ajmer Sharif Dargah', NULL, 'Khwaja Moinuddin Chishti Dargah', 'Ajmer, Rajasthan', 'India', 'india', 'sufi', '12th–13th century', 'Shrine of Khwaja Moinuddin Chishti, founder of the Chishti order in the subcontinent.', 'One of the most visited Sufi shrines in the world.', 'Annual Urs in Rajab', 'https://en.wikipedia.org/wiki/Ajmer_Sharif_Dargah', NULL, 'Dargah Sharif, Ajmer, Rajasthan 305001, India', '[{"label":"Dargah open","hours":"4:00 AM – 10:00 PM"},{"label":"Khidmat","hours":"Continuous"},{"label":"Qawwali","hours":"After Maghrib daily"}]', '["Langar (free meals)","Restroom","Ablution area","Guest houses","Shops for offerings","Parking"]', '[{"mode":"By Air","details":"Jaipur International Airport (JAI) — 135 km. Kishangarh Airport (KQH) — 30 km."},{"mode":"By Train","details":"Ajmer Junction (AII) — 2 km from Dargah. Well connected to Delhi, Mumbai, Jaipur."},{"mode":"By Road","details":"NH 48 connects Ajmer to Jaipur and Delhi. State and private buses available."}]', '{"website":"https://www.ajmer sharif.com"}', 'Khwaja Moinuddin Chishti arrived in Ajmer in 1192 and spent his life spreading the message of love and tolerance. The Chishti order became the most influential Sufi order in the Indian subcontinent.', 'The white marble dome and the massive Buland Darwaza (great gate) built by various rulers including Humayun and the Nizam of Hyderabad. The sanctum sanctorum houses the silver railing around the tomb.', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO maqams (id, name, malayalam_name, location, city, country, region, category, era, description, significance, best_time_to_visit, source_url, cover_image, address_detail, visiting_hours, facilities, how_to_reach, contact_info, history, architecture, created_from_request_id, status, created_at, updated_at) VALUES ('nizamuddin', 'Nizamuddin Dargah', NULL, 'Hazrat Nizamuddin Auliya Dargah', 'New Delhi', 'India', 'india', 'sufi', '14th century', 'Resting place of Hazrat Nizamuddin Auliya, the celebrated Chishti master of Delhi.', NULL, 'Thursday Qawwali evenings', NULL, NULL, 'Nizamuddin West, New Delhi, Delhi 110013, India', '[{"label":"Dargah open","hours":"5:00 AM – 10:00 PM"},{"label":"Qawwali","hours":"Every Thursday, 6:00 PM – 9:00 PM"}]', '["Langar","Restroom","Ablution area","Shops for offerings","Parking (nearby)"]', '[{"mode":"By Metro","details":"JLN Stadium Metro Station (Violet Line) — 1 km. Nizamuddin Railway Station — 500 m."},{"mode":"By Road","details":"Located in central Delhi. Auto-rickshaws and cabs available from all parts of the city."}]', NULL, 'Hazrat Nizamuddin Auliya was a disciple of Baba Farid and became one of the most revered Sufi saints of Delhi. His shrine has been a center of spiritual life in Delhi for over 700 years.', 'The complex includes the tomb of Nizamuddin Auliya, the Jamaat Khana mosque, and the tombs of Amir Khusrow and Jahanara Begum. The white marble tomb is set amid a marble courtyard.', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO maqams (id, name, malayalam_name, location, city, country, region, category, era, description, significance, best_time_to_visit, source_url, cover_image, address_detail, visiting_hours, facilities, how_to_reach, contact_info, history, architecture, created_from_request_id, status, created_at, updated_at) VALUES ('baghdad', 'Shaykh Abdul Qadir Jilani Shrine', NULL, 'Al-Gilani Mosque', 'Baghdad', 'Iraq', 'middle-east', 'sufi', '12th century', 'Shrine of Muhiyuddin Abdul Qadir Jilani, the Ghaus al-Azam and founder of the Qadiri order.', NULL, '11th of Rabi al-Thani (Giyarvi Sharif)', NULL, NULL, 'Bab al-Sheikh, Baghdad, Iraq', '[{"label":"Shrine open","hours":"Open 24 hours"},{"label":"Prayer times","hours":"Five daily congregational prayers"}]', '["Ablution area","Restroom","Guest house","Shops for offerings"]', '[{"mode":"By Air","details":"Baghdad International Airport (BGW) — 20 km from the shrine."},{"mode":"By Road","details":"Located in Bab al-Sheikh district, central Baghdad. Taxis are the main mode of transport."}]', NULL, 'Shaykh Abdul Qadir Jilani was born in Gilan, Persia, and settled in Baghdad where he became the most influential Sufi master of his era. The Qadiri order spread across the Islamic world and into India, Africa, and Southeast Asia.', 'The shrine features a large green dome and a vast courtyard. The tomb chamber is adorned with gold-plated railings, chandeliers, and rich carpets. The surrounding complex includes a library and several madrasas.', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO maqams (id, name, malayalam_name, location, city, country, region, category, era, description, significance, best_time_to_visit, source_url, cover_image, address_detail, visiting_hours, facilities, how_to_reach, contact_info, history, architecture, created_from_request_id, status, created_at, updated_at) VALUES ('rumi', 'Mevlana Rumi Shrine', NULL, 'Mevlana Museum', 'Konya', 'Turkey', 'middle-east', 'sufi', '13th century', 'Tomb of Mawlana Jalaluddin Rumi, the renowned Persian poet and Sufi master.', NULL, 'Şeb-i Arus (17 December)', NULL, NULL, 'Mevlana Museum, Aziziye Mahallesi, Konya, Turkey', '[{"label":"Museum open","hours":"9:00 AM – 5:30 PM (Tue–Sun)"},{"label":"Whirling Dervish","hours":"Saturdays 7:00 PM (seasonal)"}]', '["Museum shop","Cafe","Restroom","Parking","Guided tours"]', '[{"mode":"By Air","details":"Konya Airport (KYA) — 18 km from city center. Direct flights from Istanbul."},{"mode":"By Train","details":"High-speed rail from Istanbul (4.5 hours) and Ankara (1.5 hours)."},{"mode":"By Road","details":"Well connected by highway from Ankara, Istanbul, and Antalya."}]', NULL, 'Mawlana Jalaluddin Rumi came to Konya as a child and later became the leader of the Mevlevi order. His poetry, especially the Mathnawi, is considered one of the greatest spiritual works in any language.', 'The fluted turquoise dome is iconic. The interior features the tomb under a massive canopy, the dervish cells, and a priceless collection of medieval manuscripts and musical instruments.', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO maqams (id, name, malayalam_name, location, city, country, region, category, era, description, significance, best_time_to_visit, source_url, cover_image, address_detail, visiting_hours, facilities, how_to_reach, contact_info, history, architecture, created_from_request_id, status, created_at, updated_at) VALUES ('uwais', 'Uwais al-Qarani Shrine', NULL, 'Raqqa governorate', 'Raqqa', 'Syria', 'middle-east', 'sahaba', '1st century AH', 'Maqam of Uwais al-Qarani, the Yemeni follower beloved by the Prophet ﷺ.', NULL, NULL, NULL, NULL, 'Uwais al-Qarani Mosque, Raqqa Governorate, Syria', '[{"label":"Mosque open","hours":"Open 24 hours"}]', '["Mosque","Ablution area"]', '[{"mode":"By Road","details":"Located near Raqqa city. Access depends on current conditions."}]', NULL, 'Uwais al-Qarani was a Yemeni follower of the Prophet ﷺ who never met him in person but was praised by the Prophet for his devotion. He is considered a symbol of sincere love for the Prophet.', 'The shrine mosque has been rebuilt several times. The simple tomb is set within a prayer hall with white marble floors.', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO maqams (id, name, malayalam_name, location, city, country, region, category, era, description, significance, best_time_to_visit, source_url, cover_image, address_detail, visiting_hours, facilities, how_to_reach, contact_info, history, architecture, created_from_request_id, status, created_at, updated_at) VALUES ('madina-baqi', 'Jannat al-Baqi', NULL, 'Adjacent to Masjid an-Nabawi', 'Madina', 'Saudi Arabia', 'middle-east', 'sahaba', '1st century AH', 'Sacred cemetery containing many companions, family of the Prophet ﷺ, and early scholars.', 'One of the holiest burial grounds in Islam.', NULL, NULL, NULL, 'Jannat al-Baqi, Al Haram, Madina 42311, Saudi Arabia', '[{"label":"Open for Ziyarath","hours":"After Fajr to before Maghrib"},{"label":"Best times","hours":"Early morning and late afternoon"}]', '["Ablution area","Restroom","Guided information"]', '[{"mode":"By Air","details":"Prince Mohammad bin Abdulaziz Airport (MED) — 15 km from city center."},{"mode":"By Road","details":"Walking distance from Masjid an-Nabawi. Located directly to the east of the mosque."}]', NULL, 'Jannat al-Baqi was the first cemetery in Madina. The Prophet ﷺ used to visit it frequently and pray for its inhabitants. It contains the graves of many of the Prophet''s family members and closest companions.', 'The cemetery has been rebuilt and expanded over centuries. The simple stone markers follow the Islamic tradition of modest graves without elaborate structures.', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO uroos (id, title, malayalam_title, maqam_id, is_standalone, resting_person, hijri_month, hijri_month_name, hijri_day, gregorian_date, recurrence, venue_name, city, state, country, description, history, significance, program_schedule, nercha_offerings, how_to_reach, organizer_name, organizer_contact, cover_image, source_url, created_from_request_id, status, created_at, updated_at) VALUES ('chaliyam-ahmad-koya-uroos', 'Ahmad Koya Shaliyathi Uroos Mubarak', 'അഹ്മദ് കോയ ശാലിയാതി (റ) ആണ്ട് നേർച്ച', NULL, 1, 'Qutb Qasimi Shaikh Ahmad Koya Shaliyathi (റ)', 1, 'മുഹറം (Muharram)', 27, 'July / August (Annually)', 'Annual 3-day commemoration ending on Muharram 27', 'Chaliyam Juma Masjid & Azhariya Dargah Precinct', 'Chaliyam, Kozhikode', 'Kerala', 'India', 'The revered annual commemoration honoring the foremost Islamic jurist, grand mufti, and encyclopedic scholar of Malabar, Qutb Ahmad Koya Shaliyathi. Renowned for spiritual gatherings, Khatm al-Quran, and scholarly discourses.', 'Ahmad Koya Shaliyathi was among the greatest scholars in South India, celebrated for his vast Islamic library (Azhariyah) and treatises defending traditional Islamic orthodoxy.', 'A gathering of leading traditional scholars, students of sacred knowledge, and spiritual seekers celebrating the saint''s intellectual and spiritual heritage.', '[{"time":"Day 1 - 04:30 PM","event":"Kodiyettam (Flag Hoisting)","description":"Hoisting of the ceremonial Nercha flag by community scholars."},{"time":"Day 2 - 07:00 PM","event":"Grand Mawlid & Dars","description":"Recitation of praise and spiritual discourse on prophetic teachings."},{"time":"Day 3 - 10:00 AM","event":"Khatm al-Quran & Dua Majlis","description":"Collective supplication and distribution of blessed feast (Neychoru)."}]', 'Special cooked ghee rice (Neychoru), sweet delicacies, and free community meals.', '[{"mode":"By Train","details":"Feroke Railway Station (5 km) or Kozhikode Main Station (16 km)."},{"mode":"By Air","details":"Calicut International Airport (CCJ) — 18 km."},{"mode":"By Road","details":"Direct buses and autos available from Feroke, Kadalundi, and Kozhikode."}]', 'Chaliyam Azhariya Dargah Managing Committee', '+91 495 247 0122', 'https://images.unsplash.com/photo-1591604129939-f1efa4d9f7fa?auto=format&fit=crop&q=80&w=1200', 'https://ziyarathinfo.wordpress.com/2015/03/05/%e0%b4%85%e0%b4%b9%e0%b5%8d%e0%b4%ae%e0%b4%a6%e0%b5%8d-%e0%b4%95%e0%b5%8b%e0%b4%af%e0%b4%b6%e0%b4%be%e0%b4%b2%e0%b4%bf%e0%b4%af%e0%b4%be%e0%b4%a4%e0%b4%bf-%e0%b4%b1-%e0%b4%9a%e0%b4%be%e0%b4%b2/', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO uroos (id, title, malayalam_title, maqam_id, is_standalone, resting_person, hijri_month, hijri_month_name, hijri_day, gregorian_date, recurrence, venue_name, city, state, country, description, history, significance, program_schedule, nercha_offerings, how_to_reach, organizer_name, organizer_contact, cover_image, source_url, created_from_request_id, status, created_at, updated_at) VALUES ('noonjeri-shaikh-uroos', 'Shaikh Kunji Ahmad Noonjeri Uroos', 'ശൈഖ് കുഞ്ഞി അഹ്മദ് (റ) നൂഞ്ഞേരി നേർച്ച', NULL, 1, 'Shaikh Kunji Ahmad Valiyullah (Noonjeri Shaikh)', 1, 'മുഹറം (Muharram)', 28, 'July / August (Annually)', 'Annual commemoration on Muharram 28', 'Noonjeri Dargah Sharif', 'Kannur', 'Kerala', 'India', 'Commemorating the revered mystic and saint Noonjeri Shaikh, whose spiritual benevolence and guidance drew seekers across North Malabar.', 'The saint spent his life in spiritual contemplation, service of the poor, and teaching moral rectitude in the Kannur region.', 'A renowned local gathering characterized by serene spiritual recitations and widespread distribution of blessed community food.', '[{"time":"05:00 PM","event":"Majlisun-Noor","description":"All-night spiritual litanies and collective supplication."},{"time":"08:00 PM","event":"Spiritual Discourse","description":"Eminent scholars speak on the virtues of saints."}]', 'Traditional sweet offerings and community meals.', '[{"mode":"By Train","details":"Kannur Railway Station — 14 km."},{"mode":"By Air","details":"Kannur International Airport (CNN) — 24 km."}]', 'Noonjeri Dargah Sharif Committee', '+91 497 270 4455', 'https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&q=80&w=1200', 'https://ziyarathinfo.wordpress.com/2015/03/05/%e0%b4%b6%e0%b5%88%e0%b4%96%e0%b5%8d-%e0%b4%95%e0%b5%81%e0%b4%9e%e0%b5%8d%e0%b4%9e%e0%b4%bf-%e0%b4%85%e0%b4%b9%e0%b5%8d%e0%b4%ae%e0%b4%a6%e0%b5%8d-%e0%b4%b1-%e0%b4%a8%e0%b5%82%e0%b4%9e%e0%b5%8d/', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO uroos (id, title, malayalam_title, maqam_id, is_standalone, resting_person, hijri_month, hijri_month_name, hijri_day, gregorian_date, recurrence, venue_name, city, state, country, description, history, significance, program_schedule, nercha_offerings, how_to_reach, organizer_name, organizer_contact, cover_image, source_url, created_from_request_id, status, created_at, updated_at) VALUES ('perumpadappu-puthanpalli-uroos', 'Perumpadappu Puthanpalli Uroos Mubarak', 'പെരുമ്പടപ്പ് പുത്തൻപള്ളി ആണ്ട് നേർച്ച', NULL, 1, 'Kunjahammad Musliyar (Perumpadappu Puthanpalli)', 2, 'സ്വഫർ (Safar)', 24, 'August / September (Annually)', 'Annual multi-day commemoration concluding on Safar 24', 'Perumpadappu Puthanpalli Juma Masjid & Dargah', 'Perumpadappu, Malappuram', 'Kerala', 'India', 'One of the most famous historical nerchas of coastal Malappuram, drawing thousands for sacred Neychoru distribution, spiritual majlis, and communal harmony.', 'Celebrated for over a century, the Puthanpalli Nercha is deeply woven into the cultural and spiritual fabric of South Malabar.', 'Famous for massive distribution of blessed ghee rice to all visitors irrespective of caste or creed, symbolising selfless hospitality.', '[{"time":"Day 1 - 05:00 PM","event":"Kodiyettam","description":"Ceremonial flag hoisting initiating the festival."},{"time":"Every Evening","event":"Mawlid Majlis & Lectures","description":"Spiritual lectures by leading Islamic orators."},{"time":"Final Day","event":"Maha Annadanam","description":"Grand distribution of traditional Neychoru to thousands."}]', 'Renowned Puthanpalli cooked ghee rice (Neychoru).', '[{"mode":"By Train","details":"Guruvayur Station — 18 km, or Tirur Station — 28 km."},{"mode":"By Road","details":"Well-connected by KSRTC and private buses via Ponnani and Chavakkad."}]', 'Perumpadappu Puthanpalli Jama''ath Committee', '+91 494 267 8900', 'https://images.unsplash.com/photo-1564769625905-50e93615e769?auto=format&fit=crop&q=80&w=1200', 'https://ziyarathinfo.wordpress.com/2015/03/05/%e0%b4%95%e0%b5%81%e0%b4%9e%e0%b5%8d%e0%b4%9e%e0%b4%b9%e0%b4%ae%e0%b5%8d%e0%b4%ae%e0%b4%a6%e0%b5%8d-%e0%b4%ae%e0%b5%81%e0%b4%b8%e0%b5%8d%e2%80%8c%e0%b4%b2%e0%b4%bf%e0%b4%af%e0%b4%be%e0%b4%b0%e0%b5%8d/', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO uroos (id, title, malayalam_title, maqam_id, is_standalone, resting_person, hijri_month, hijri_month_name, hijri_day, gregorian_date, recurrence, venue_name, city, state, country, description, history, significance, program_schedule, nercha_offerings, how_to_reach, organizer_name, organizer_contact, cover_image, source_url, created_from_request_id, status, created_at, updated_at) VALUES ('mampuram-uroos', 'Mampuram Annual Uroos Mubarak', 'മമ്പുറം ആണ്ട് നേർച്ച', 'mampuram', 0, 'Sayyid Alavi Thangal & Sayyid Fazal Pookoya Thangal', 3, 'റബീഉൽ അവ്വൽ (Rabi al-Awwal)', 7, 'September / October (Annually)', 'Annual 8-day commemoration from Rabi al-Awwal 1 to 8', 'Mampuram Juma Masjid & Dargah Sharif', 'Tirurangadi, Malappuram', 'Kerala', 'India', 'The prestigious annual gathering commemorating Qutubuzzaman Sayyid Alavi Thangal. Pilgrims from across India congregate for spiritual dars, Mawlid recitations, and community feast (Neychoru).', 'Celebrated for over two centuries since the era of the Mampuram Thangals, this Uroos played a profound historic role in unifying the Malabar community and preserving Islamic spiritual scholarship.', 'One of the largest spiritual congregations in South India, celebrated with reverence, spiritual lectures, and widespread food distribution to thousands of seekers.', '[{"time":"Day 1 - 04:30 PM","event":"Kodiyettam (Flag Hoisting)","description":"Official hoisting of the Nercha flag by community elders and Thangals."},{"time":"Daily - 07:00 PM","event":"Spiritual Majlis & Dars","description":"Renowned Islamic scholars address gatherings on prophetic heritage and morality."},{"time":"Day 7 - 08:00 PM","event":"Grand Mawlid & Dua Majlis","description":"All-night collective recitation and special supplication."},{"time":"Final Day - 11:00 AM","event":"Neychoru Annadanam","description":"Mass distribution of sacred feast to tens of thousands of visitors."}]', 'Special cooked ghee rice (Neychoru), sweet offerings, and holy flag rituals.', '[{"mode":"By Air","details":"Calicut International Airport (CCJ) — 22 km. Direct cabs and express buses available."},{"mode":"By Train","details":"Parappanangadi (PGI) Railway Station — 10 km. Tirur Station — 18 km."},{"mode":"By Road","details":"National Highway 66 connects directly to Tirurangadi. Special KSRTC bus services operate during festival days."}]', 'Mampuram Dargah Sharif Managing Committee', '+91 494 246 0222 / info@mampuram.org', 'https://images.unsplash.com/photo-1591604129939-f1efa4d9f7fa?auto=format&fit=crop&q=80&w=1200', 'https://en.wikipedia.org/wiki/Mamburam_Thangal', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO uroos (id, title, malayalam_title, maqam_id, is_standalone, resting_person, hijri_month, hijri_month_name, hijri_day, gregorian_date, recurrence, venue_name, city, state, country, description, history, significance, program_schedule, nercha_offerings, how_to_reach, organizer_name, organizer_contact, cover_image, source_url, created_from_request_id, status, created_at, updated_at) VALUES ('kanniyath-ahmad-musliyar-uroos', 'Kanniyath Usthad Commemoration Uroos', 'കണ്ണിയത്ത് അഹ്മദ് മുസ്‌ലിയാർ ആണ്ട് അനുസ്മരണം', NULL, 1, 'Raisul Ulama Kanniyath Ahmad Musliyar (റ)', 4, 'റബീഉൽ ആഖർ (Rabi al-Thani)', 2, 'October / November (Annually)', 'Annual commemoration on Rabi al-Thani 2', 'Kanniyath Maqam Precinct, Karakkunnu', 'Malappuram', 'Kerala', 'India', 'Annual commemoration honoring the spiritual master, scholar of scholars, and revered Supreme President of Samastha Kerala Jam''iyyathul Ulama, Kanniyath Ahmad Musliyar.', 'Known for his saintly demeanor, photographic memory, and profound devotion to Sunnah, Kanniyath Usthad led the community for decades with unmatched wisdom.', 'A day of intense spiritual reflection, scholarly discourses, and community prayers drawing teachers and students of traditional Madrasas.', '[{"time":"09:00 AM","event":"Ziyarath Majlis","description":"Collective ziyarath and prayer at the sacred tomb."},{"time":"02:00 PM","event":"Scholarly Symposium","description":"Presentations on Kanniyath Usthad''s contributions to Fiqh and Hadith."},{"time":"07:30 PM","event":"Grand Dua Majlis","description":"Closing supplication led by community elders."}]', 'Annadanam and distribution of Islamic educational literature.', '[{"mode":"By Train","details":"Angadipuram Station — 20 km."},{"mode":"By Air","details":"Calicut International Airport — 35 km."}]', 'Kanniyath Usthad Memorial Trust', '+91 483 273 1199', 'https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&q=80&w=1200', 'https://ziyarathinfo.wordpress.com/2015/03/05/%e0%b4%95%e0%b4%a3%e0%b5%8d%e0%b4%a3%e0%b4%bf%e0%b4%af%e0%b4%a4%e0%b5%8d%e0%b4%a4%e0%b5%8d-%e0%b4%85%e0%b4%b9%e0%b5%8d%e0%b4%ae%e0%b4%a6%e0%b5%8d-%e0%b4%ae%e0%b5%81%e0%b4%b8%e0%b5%8d%e2%80%8c%e0%b4%b2/', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO uroos (id, title, malayalam_title, maqam_id, is_standalone, resting_person, hijri_month, hijri_month_name, hijri_day, gregorian_date, recurrence, venue_name, city, state, country, description, history, significance, program_schedule, nercha_offerings, how_to_reach, organizer_name, organizer_contact, cover_image, source_url, created_from_request_id, status, created_at, updated_at) VALUES ('madavoor-uroos', 'C.M. Valiyullah Madavoor Uroos Mubarak', 'സി.എം. വലിയുള്ളാഹി മടവൂർ ആണ്ട് നേർച്ച', 'madavoor', 0, 'Sayyid Muhammad Mouladaveela C.M. Valiyullah', 4, 'റബീഉൽ ആഖർ (Rabi al-Thani)', 4, 'October / November (Annually)', 'Annual 5-day spiritual convention', 'Madavoor C.M. Maqam Sharif', 'Madavoor, Kozhikode', 'Kerala', 'India', 'A major spiritual pilgrimage in North Malabar honoring the celebrated 20th-century mystic C.M. Valiyullah. Features all-night prayers, Quranic recitations, and social feeding.', 'C.M. Valiyullah was one of the most beloved Ba''alawi spiritual masters of modern Kerala, celebrated for miracles (karamat) and spiritual succour to people of all backgrounds.', 'Thousands gather for collective Thasbeeh prayers, recitation of Haddad Ratheeb, and community harmony.', '[{"time":"Day 1 - 05:00 PM","event":"Kodiyettam & Ziyarath","description":"Ceremonial flag hoisting and opening prayers."},{"time":"Nightly - 08:00 PM","event":"Spiritual Majlis","description":"Dhikr assemblies and blessings."},{"time":"Final Day","event":"Neychoru Distribution","description":"Community annadanam to over 50,000 seekers."}]', 'Sacred ghee rice (Neychoru) and sweet offerings.', '[{"mode":"By Train","details":"Kozhikode Railway Station — 22 km."},{"mode":"By Air","details":"Calicut International Airport — 40 km."}]', 'Madavoor C.M. Center Managing Committee', '+91 495 285 6200', 'https://images.unsplash.com/photo-1591604129939-f1efa4d9f7fa?auto=format&fit=crop&q=80&w=1200', NULL, NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO uroos (id, title, malayalam_title, maqam_id, is_standalone, resting_person, hijri_month, hijri_month_name, hijri_day, gregorian_date, recurrence, venue_name, city, state, country, description, history, significance, program_schedule, nercha_offerings, how_to_reach, organizer_name, organizer_contact, cover_image, source_url, created_from_request_id, status, created_at, updated_at) VALUES ('ambakkunnu-beeran-auliya-uroos', 'Beeran Auliya Ambakkunnu Uroos', 'ബീരാൻ ഔലിയ (റ) അമ്പങ്കുന്ന് നേർച്ച', NULL, 1, 'Beeran Auliya (റ)', 4, 'റബീഉൽ ആഖർ (Rabi al-Thani)', 12, 'November (Annually)', 'Annual 3-day nercha culminating on Rabi al-Thani 12', 'Ambakkunnu Dargah Sharif', 'Ambakkunnu, Malappuram', 'Kerala', 'India', 'Spiritual commemoration of Beeran Auliya in Ambakkunnu, famed for prayer congregations, community benevolence, and traditional nercha customs.', 'A renowned local sanctuary where devotees across Malappuram have sought solace and blessings for generations.', 'Marked by deep devotional singing, Mawlid majlis, and communal harmony.', '[{"time":"05:00 PM","event":"Flag Hoisting","description":"Opening ceremony."},{"time":"07:30 PM","event":"Spiritual Majlis","description":"Traditional remembrance assembly."}]', 'Neychoru and sweet distribution.', '[{"mode":"By Train","details":"Tirur Station — 15 km."}]', 'Ambakkunnu Dargah Committee', '+91 494 250 8822', 'https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&q=80&w=1200', 'https://ziyarathinfo.wordpress.com/2015/03/05/%e0%b4%ac%e0%b5%80%e0%b4%b0%e0%b4%be%e0%b4%a8%e0%b5%8d%e2%80%8d-%e0%b4%94%e0%b4%b2%e0%b4%bf%e0%b4%af-%e0%b4%b1-%e0%b4%85%e0%b4%ae%e0%b5%8d%e0%b4%aa%e0%b4%99%e0%b5%8d%e0%b4%95%e0%b5%81%e0%b4%a8/', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO uroos (id, title, malayalam_title, maqam_id, is_standalone, resting_person, hijri_month, hijri_month_name, hijri_day, gregorian_date, recurrence, venue_name, city, state, country, description, history, significance, program_schedule, nercha_offerings, how_to_reach, organizer_name, organizer_contact, cover_image, source_url, created_from_request_id, status, created_at, updated_at) VALUES ('vellore-abdul-wahab-uroos', 'Hazrat Baani Shaikh Abdul Wahab Uroos', 'ബാനി ഹസ്‌റത്ത് ശൈഖ് അബ്ദുൽ വഹാബ് (റ) ആണ്ട്, വെല്ലൂർ', NULL, 1, 'Allama Baani Hazrat Shaikh Abdul Wahab (റ)', 4, 'റബീഉൽ ആഖർ (Rabi al-Thani)', 22, 'November (Annually)', 'Annual graduation and commemoration assembly', 'Madrasa al-Baqiyathus Salihat Dargah & Campus', 'Vellore', 'Tamil Nadu', 'India', 'Annual commemoration of the founder of the illustrious Baqiyathus Salihat Arabic College in Vellore, which has trained thousands of Islamic scholars across South India and Kerala.', 'Founded in 1857, Baqiyathus Salihat was a spiritual beacon of Islamic scholarship, resisting colonial disruptions and reviving classical sciences.', 'A reunion of thousands of Baqavi scholars and seekers from Tamil Nadu, Kerala, Karnataka, and Lakshadweep.', '[{"time":"09:00 AM","event":"Sanad Danam (Convocation)","description":"Awarding of Baqavi degrees to graduating scholars."},{"time":"04:00 PM","event":"Ziyarath at Baani Hazrat Tomb","description":"Collective prayers for the pioneer of Islamic education."}]', 'Special Tabarruk and mass feast for delegates and guests.', '[{"mode":"By Train","details":"Katpadi Junction (Vellore) — 6 km."},{"mode":"By Air","details":"Chennai International Airport — 135 km, Bengaluru Airport — 200 km."}]', 'Baqiyathus Salihat Arabic College Trust', '+91 416 222 3456', 'https://images.unsplash.com/photo-1564769625905-50e93615e769?auto=format&fit=crop&q=80&w=1200', 'https://ziyarathinfo.wordpress.com/2015/03/05/%e0%b4%ac%e0%b4%be%e0%b4%a8%e0%b4%bf-%e0%b4%b9%e0%b4%b8%e0%b5%8d%e0%b4%b0%e0%b4%a4%e0%b5%8d-%e0%b4%b6%e0%b5%88%e0%b4%96%e0%b5%8d-%e0%b4%85%e0%b4%ac%e0%b5%8d%e0%b4%a6%e0%b5%81%e0%b4%b2%e0%b5%8d/', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO uroos (id, title, malayalam_title, maqam_id, is_standalone, resting_person, hijri_month, hijri_month_name, hijri_day, gregorian_date, recurrence, venue_name, city, state, country, description, history, significance, program_schedule, nercha_offerings, how_to_reach, organizer_name, organizer_contact, cover_image, source_url, created_from_request_id, status, created_at, updated_at) VALUES ('imam-al-haramayn-uroos', 'Imam al-Haramayn al-Juwayni Commemoration', 'ഇമാമുൽ ഹറമൈനി അൽ ജുവൈനി അനുസ്മരണം', NULL, 1, 'Imam al-Haramayn Abdul Malik al-Juwayni (റ)', 4, 'റബീഉൽ ആഖർ (Rabi al-Thani)', 25, 'November (Annually)', 'Annual scholarly commemoration', 'Nishapur Historical Scholar Complex', 'Nishapur', 'Razavi Khorasan', 'Iran', 'Global spiritual commemoration of Imam al-Haramayn, author of Nihayat al-Matlab, supreme teacher at Nizamiyya of Nishapur, and mentor to Imam Abu Hamid al-Ghazali.', 'He taught in Makkah and Madinah for years, earning the supreme honorary title ''Imam of the Two Sanctuaries'' (Imam al-Haramayn).', 'Honored as the fountainhead of Shafi''i jurisprudence and Ash''ari theological formulation.', '[{"time":"09:00 AM","event":"Scholarly Symposium","description":"Readings from Kitab al-Irshad and Nihayat al-Matlab."}]', 'Scholarly publication endowments and commemorative charity.', '[{"mode":"By Air","details":"Mashhad International Airport (MHD) — 110 km."}]', 'International Classical Islamic Heritage Forum', 'info@heritage-islamic.org', 'https://images.unsplash.com/photo-1591604129939-f1efa4d9f7fa?auto=format&fit=crop&q=80&w=1200', 'https://ziyarathinfo.wordpress.com/2015/03/02/%e0%b4%87%e0%b4%ae%e0%b4%be%e0%b4%ae%e0%b5%81%e0%b4%b2%e0%b5%8d%e2%80%8d-%e0%b4%b9%e0%b4%b1%e0%b4%ae%e0%b5%88%e0%b4%a8%e0%b4%bf/', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO uroos (id, title, malayalam_title, maqam_id, is_standalone, resting_person, hijri_month, hijri_month_name, hijri_day, gregorian_date, recurrence, venue_name, city, state, country, description, history, significance, program_schedule, nercha_offerings, how_to_reach, organizer_name, organizer_contact, cover_image, source_url, created_from_request_id, status, created_at, updated_at) VALUES ('cheruvannur-vadakara-muhammad-haji-uroos', 'Vadakara Muhammad Haji Uroos', 'വടകര മുഹമ്മദ് ഹാജി (റ) ചെറുവണ്ണൂർ ആണ്ട്', NULL, 1, 'Shaikh Vadakara Muhammad Haji (റ)', 4, 'റബീഉൽ ആഖർ (Rabi al-Thani)', 29, 'November (Annually)', 'Annual commemoration on Rabi al-Thani 29', 'Cheruvannur Juma Masjid & Dargah', 'Cheruvannur, Kozhikode', 'Kerala', 'India', 'Annual festival commemorating the pious saint Vadakara Muhammad Haji, bringing together thousands for Quranic recitations and remembrance majlis.', 'Beloved among the common folk of Malabar for his prayers, humility, and unwavering spiritual presence in Cheruvannur.', 'A beloved gathering marked by peaceful spiritual fellowship, collective supplication, and food distribution.', '[{"time":"05:30 PM","event":"Mawlid & Ziyarath","description":"Evening prayers at the Maqam."},{"time":"08:00 PM","event":"Annadanam","description":"Community feast."}]', 'Neychoru and sweets.', '[{"mode":"By Train","details":"Feroke Station — 3 km, Kozhikode Station — 9 km."}]', 'Cheruvannur Dargah Managing Committee', '+91 495 248 1144', 'https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&q=80&w=1200', 'https://ziyarathinfo.wordpress.com/2015/03/05/%e0%b4%9a%e0%b5%86%e0%b4%b1%e0%b5%81%e0%b4%b5%e0%b4%a3%e0%b5%8d%e0%b4%a3%e0%b5%82%e0%b4%b0%e0%b5%8d%e2%80%8d-%e0%b4%ae%e0%b5%81%e0%b4%b9%e0%b4%ae%e0%b5%8d%e0%b4%ae%e0%b4%a6%e0%b5%8d-%e0%b4%b9%e0%b4%be/', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO uroos (id, title, malayalam_title, maqam_id, is_standalone, resting_person, hijri_month, hijri_month_name, hijri_day, gregorian_date, recurrence, venue_name, city, state, country, description, history, significance, program_schedule, nercha_offerings, how_to_reach, organizer_name, organizer_contact, cover_image, source_url, created_from_request_id, status, created_at, updated_at) VALUES ('beemapally-uroos', 'Beemapally Annual Uroos Mubarak', 'ബീമാപള്ളി ഉറൂസ് മുബാറക് (ചന്ദനക്കുടം മഹോത്സവം)', 'beemapally', 0, 'Sayyidathunissa Beema Umma & Sayyidussaheed Maheen Abubacker', 5, 'ജമാദുൽ അവ്വൽ (Jumada al-Awwal)', 1, 'December / January (Annually)', '10-day grand festival culminating on Jumada al-Awwal 10', 'Beemapally Muslim Jama''ath Dargah Sharif', 'Thiruvananthapuram', 'Kerala', 'India', 'One of the largest, oldest, and most inclusive spiritual congregations in South Kerala. Millions attend the sacred Chandanakkudam procession, special du''a majlis, and spiritual feast.', 'Beema Umma and her son Maheen Abubacker arrived from Arabia centuries ago, preaching love, healing the sick, and laying the foundations of communal brotherhood in Travancore.', 'Famed for unity across faiths, traditional Chandanakkudam pots carried in devotion, and spiritual supplications.', '[{"time":"Day 1 - 04:30 PM","event":"Grand Flag Hoisting","description":"Inaugurated by religious leaders and community elders."},{"time":"Daily - 08:00 PM","event":"Praise & Mawlid Assembly","description":"Devotional gatherings throughout the night."},{"time":"Final Night","event":"Chandanakkudam Procession","description":"Sacred procession and collective prayer."}]', 'Neychoru, sweet puddings, and scented incense offerings.', '[{"mode":"By Train","details":"Thiruvananthapuram Central (TVC) — 8 km."},{"mode":"By Air","details":"Trivandrum International Airport (TRV) — 5 km."}]', 'Beemapally Muslim Jama''ath Managing Committee', '+91 471 238 2145', 'https://images.unsplash.com/photo-1564769625905-50e93615e769?auto=format&fit=crop&q=80&w=1200', NULL, NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO uroos (id, title, malayalam_title, maqam_id, is_standalone, resting_person, hijri_month, hijri_month_name, hijri_day, gregorian_date, recurrence, venue_name, city, state, country, description, history, significance, program_schedule, nercha_offerings, how_to_reach, organizer_name, organizer_contact, cover_image, source_url, created_from_request_id, status, created_at, updated_at) VALUES ('imam-suyuti-uroos', 'Imam Jalaluddin al-Suyuti Commemoration', 'ഇമാം സുയൂഥ്വി (റ) ആണ്ട് അനുസ്മരണം', NULL, 1, 'Imam Jalaluddin Abd al-Rahman al-Suyuti (റ)', 5, 'ജമാദുൽ അവ്വൽ (Jumada al-Awwal)', 19, 'December (Annually)', 'Annual scholarly commemoration', 'Bab al-Qarafa, Southern Cemetery', 'Cairo', 'Cairo Governorate', 'Egypt', 'Commemorating the encyclopedic Hadith master, Quran commentator, and polymath Imam al-Suyuti, author of Tafsir al-Jalalayn, al-Itqan fi Ulum al-Qur''an, and hundreds of classical Islamic texts.', 'A towering Egyptian luminary of the Mamluk era who attained the rank of Mujtahid, celebrated worldwide for his literary output.', 'Recognized by Islamic universities globally as one of the most prolific authors in human history.', '[{"time":"10:00 AM","event":"Symposium on Ulum al-Hadith","description":"Scholarly lectures in Cairo and partner institutions."}]', 'Charity to students of Al-Azhar University.', '[{"mode":"By Air","details":"Cairo International Airport (CAI) — 20 km."}]', 'Egyptian Classical Waqf Heritage Council', 'contact@azhar-heritage.eg', 'https://images.unsplash.com/photo-1591604129939-f1efa4d9f7fa?auto=format&fit=crop&q=80&w=1200', 'https://ziyarathinfo.wordpress.com/2015/02/26/%e0%b4%87%e0%b4%ae%e0%b4%be%e0%b4%82-%e0%b4%b8%e0%b5%81%e0%b4%af%e0%b5%82%e0%b4%a5%e0%b5%8d%e0%b4%b5%e0%b4%bf%e0%b4%b1-%e0%b4%88%e0%b4%9c%e0%b4%bf%e0%b4%aa%e0%b5%8d%e0%b4%a4%e0%b5%8d%e2%80%8c/', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO uroos (id, title, malayalam_title, maqam_id, is_standalone, resting_person, hijri_month, hijri_month_name, hijri_day, gregorian_date, recurrence, venue_name, city, state, country, description, history, significance, program_schedule, nercha_offerings, how_to_reach, organizer_name, organizer_contact, cover_image, source_url, created_from_request_id, status, created_at, updated_at) VALUES ('valakkulam-koyamutti-wali-uroos', 'Koyamutti Wali Valakkulam Uroos', 'കോയാമുട്ടി വലി (റ) വാളക്കുളം നേർച്ച', NULL, 1, 'Sayyid Koyamutti Wali (റ)', 6, 'ജമാദുൽ ആഖർ (Jumada al-Thani)', 20, 'January (Annually)', 'Annual 3-day nercha concluding on Jumada al-Thani 20', 'Valakkulam Dargah Sharif', 'Valakkulam, Malappuram', 'Kerala', 'India', 'Commemorating the revered mystic Sayyid Koyamutti Wali with all-night dhikr majlis, feeding of pilgrims, and spiritual litanies.', 'The shrine at Valakkulam has served as an oasis of peace, mediation, and prayer for the local community for generations.', 'Spiritual recitations, community prayer gatherings, and harmonious participation across all sections of society.', '[{"time":"05:00 PM","event":"Kodiyettam","description":"Flag hoisting ceremony."},{"time":"07:30 PM","event":"Dhikr & Dua Majlis","description":"Night-long remembrance."}]', 'Traditional cooked Neychoru and sweets.', '[{"mode":"By Train","details":"Tirur Railway Station — 18 km."},{"mode":"By Road","details":"Easily accessible from Kottakkal and Malappuram town."}]', 'Valakkulam Dargah Committee', '+91 483 274 5511', 'https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&q=80&w=1200', 'https://ziyarathinfo.wordpress.com/2015/03/05/%e0%b4%95%e0%b5%8b%e0%b4%af%e0%b4%be%e0%b4%ae%e0%b5%81%e0%b4%9f%e0%b5%8d%e0%b4%9f%e0%b4%bf-%e0%b4%b5%e0%b4%b2%e0%b4%bf%e0%b4%b1-%e0%b4%b5%e0%b4%be%e0%b4%b3%e0%b4%95%e0%b5%8d%e0%b4%95%e0%b5%81/', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO uroos (id, title, malayalam_title, maqam_id, is_standalone, resting_person, hijri_month, hijri_month_name, hijri_day, gregorian_date, recurrence, venue_name, city, state, country, description, history, significance, program_schedule, nercha_offerings, how_to_reach, organizer_name, organizer_contact, cover_image, source_url, created_from_request_id, status, created_at, updated_at) VALUES ('ajmer-khwaja-muinuddin-uroos', 'Ajmer Sharif Khwaja Gharib Nawaz Grand Uroos', 'അജ്മീർ ഖാജാ മുഈനുദ്ദീൻ ചിശ്തി (റ) മഹാ ഉറൂസ്', 'ajmer', 0, 'Sultan-ul-Hind Khwaja Moinuddin Chishti (റ)', 7, 'റജബ് (Rajab)', 6, 'January / February (Annually)', 'Annual 6-day World Uroos from Rajab 1 to 6', 'Dargah Sharif of Khwaja Moinuddin Chishti', 'Ajmer', 'Rajasthan', 'India', 'The internationally famed annual Uroos Mubarak of Khwaja Gharib Nawaz. Over a million seekers, scholars, and pilgrims from across the globe assemble for the opening of the Jannati Darwaza, holy Chhati Sharif, Langar Khana distribution, and Qawwali devotional gatherings.', 'Khwaja Gharib Nawaz brought the spiritual light of love, peace, and universal brotherhood to the Indian subcontinent in the 12th century, touching millions of lives.', 'The pinnacle of Sufi gatherings in Asia, epitomizing the phrase ''Love toward all, malice toward none''.', '[{"time":"Rajab 1","event":"Opening of Jannati Darwaza","description":"Sacred gate opened for pilgrims."},{"time":"Nightly","event":"Mehfil-e-Sama & Qawwali","description":"Spiritual poetry in the Mehfil Khana."},{"time":"Rajab 6","event":"Qul & Chhati Sharif","description":"Grand concluding ceremony and prayers."}]', 'Maha Degh distribution: Sweet rice and saffron delicacies cooked in giant cauldrons.', '[{"mode":"By Train","details":"Ajmer Junction (AII) — 1.5 km."},{"mode":"By Air","details":"Kishangarh Airport (KQH) — 30 km, Jaipur Airport (JAI) — 135 km."}]', 'Dargah Committee & Anjuman Yadgar-e-Chishtia', '+91 145 242 9034', 'https://images.unsplash.com/photo-1591604129939-f1efa4d9f7fa?auto=format&fit=crop&q=80&w=1200', 'https://ziyarathinfo.wordpress.com/2015/02/23/%e0%b4%85%e0%b4%9c%e0%b5%8d%e0%b4%ae%e0%b5%80%e0%b4%b0%e0%b5%8d%e2%80%8d-%e0%b4%96%e0%b4%be%e0%b4%9c%e0%b4%be-%e0%b4%ae%e0%b5%81%e0%b4%88%e0%b4%a8%e0%b5%81%e0%b4%a6%e0%b5%8d%e0%b4%a6%e0%b5%80%e0%b4%a8/', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO uroos (id, title, malayalam_title, maqam_id, is_standalone, resting_person, hijri_month, hijri_month_name, hijri_day, gregorian_date, recurrence, venue_name, city, state, country, description, history, significance, program_schedule, nercha_offerings, how_to_reach, organizer_name, organizer_contact, cover_image, source_url, created_from_request_id, status, created_at, updated_at) VALUES ('thattangara-kuttiyamu-musliyar-uroos', 'Kuttiyamu Musliyar Thattangara Uroos', 'കുട്ട്യാമു മുസ്‌ലിയാർ (ഖ.സി) തട്ടാങ്ങര ആണ്ട്', NULL, 1, 'Shaikh Kuttiyamu Musliyar (ഖ.സി)', 7, 'റജബ് (Rajab)', 10, 'February (Annually)', 'Annual commemoration on Rajab 10', 'Thattangara Juma Masjid & Maqam', 'Thattangara, Malappuram', 'Kerala', 'India', 'Sacred annual commemoration of Kuttiyamu Musliyar, renowned scholar and Sufi master of Valluvanad.', 'Dedicated his life to teaching Quranic disciplines and resolving disputes with deep Islamic jurisprudence and compassion.', 'A peaceful retreat for spiritual meditation and community dua majlis.', '[{"time":"05:00 PM","event":"Ziyarath Majlis","description":"Opening prayer at the tomb."},{"time":"08:00 PM","event":"Annadanam","description":"Food distribution to pilgrims."}]', 'Neychoru and food.', '[{"mode":"By Train","details":"Tirur Railway Station — 24 km."}]', 'Thattangara Maqam Committee', '+91 494 255 1010', 'https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&q=80&w=1200', 'https://ziyarathinfo.wordpress.com/2015/03/05/%e0%b4%95%e0%b5%81%e0%b4%9f%e0%b5%8d%e0%b4%9f%e0%b5%8d%e0%b4%af%e0%b4%be%e0%b4%ae%e0%b5%81-%e0%b4%ae%e0%b5%81%e0%b4%b8%e0%b5%8d%e2%80%8c%e0%b4%b2%e0%b4%bf%e0%b4%af%e0%b4%be%e0%b4%b0%e0%b5%8d%e2%80%8d/', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO uroos (id, title, malayalam_title, maqam_id, is_standalone, resting_person, hijri_month, hijri_month_name, hijri_day, gregorian_date, recurrence, venue_name, city, state, country, description, history, significance, program_schedule, nercha_offerings, how_to_reach, organizer_name, organizer_contact, cover_image, source_url, created_from_request_id, status, created_at, updated_at) VALUES ('kondotty-nercha', 'Kondotty Nercha Mubarak', 'കൊണ്ടോട്ടി നേർച്ച', 'kondotty', 0, 'Muhammad Shah Thangal (First Thangal of Kondotty)', 7, 'റജബ് (Rajab)', 14, 'February / March (Annually)', 'Annual 3-day festival in the month of Rajab', 'Kondotty Qubba & Dargah Sharif', 'Kondotty, Malappuram', 'Kerala', 'India', 'A celebrated 18th-century heritage nercha held at Kondotty Qubba with religious processions, spiritual Qawwali, cannons, and mass feast.', 'Originating in the 18th century, the Kondotty Nercha is celebrated for its composite Malabar culture, Persian-influenced architecture, and deep spiritual traditions.', 'One of the most visually stunning cultural and spiritual spectacles of Kerala, famous for communal amity.', '[{"time":"Day 1 - 04:00 PM","event":"Kodiyettam & Procession","description":"Ceremonial flag hoisting and traditional cannon salute."},{"time":"Nightly","event":"Qawwali & Sama Majlis","description":"Spiritual devotional music and Mawlid recitations."},{"time":"Final Day","event":"Maha Annadanam","description":"Community feast."}]', 'Special sweet Neychoru and fragrant offerings.', '[{"mode":"By Air","details":"Calicut International Airport — 3 km."},{"mode":"By Train","details":"Feroke Station — 18 km."}]', 'Kondotty Qubba Managing Committee', '+91 483 271 2233', 'https://images.unsplash.com/photo-1564769625905-50e93615e769?auto=format&fit=crop&q=80&w=1200', NULL, NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO uroos (id, title, malayalam_title, maqam_id, is_standalone, resting_person, hijri_month, hijri_month_name, hijri_day, gregorian_date, recurrence, venue_name, city, state, country, description, history, significance, program_schedule, nercha_offerings, how_to_reach, organizer_name, organizer_contact, cover_image, source_url, created_from_request_id, status, created_at, updated_at) VALUES ('imam-tirmidhi-uroos', 'Imam Abu Isa al-Tirmidhi Commemoration', 'ഇമാം തിർമിദി (റ) ആണ്ട് അനുസ്മരണം', NULL, 1, 'Imam Abu Isa Muhammad al-Tirmidhi (റ)', 7, 'റജബ് (Rajab)', 13, 'February (Annually)', 'Annual international commemoration', 'Hakim at-Tirmizi Memorial Complex, Termez', 'Termez', 'Surxondaryo Region', 'Uzbekistan', 'Spiritual commemoration honoring the compiler of Jami'' at-Tirmidhi and Ash-Shama''il al-Muhammadiyya, highlighting prophetic characteristics and authentic traditions.', 'A blind scholar of astonishing memory, who traveled across Khurasan, Iraq, and the Hejaz to preserve prophetic Sunnah.', 'His Shama''il continues to be recited in Kerala and global majlises as the standard biography of the Prophet''s sublime character.', '[{"time":"10:00 AM","event":"Shama''il al-Mustafa Majlis","description":"Recitation of prophetic physical and moral attributes."}]', 'Scholarly awards and charitable endowments.', '[{"mode":"By Air","details":"Termez Airport (TMJ) — 8 km."}]', 'International Tirmidhi Heritage Foundation', 'contact@tirmidhi-memorial.uz', 'https://images.unsplash.com/photo-1591604129939-f1efa4d9f7fa?auto=format&fit=crop&q=80&w=1200', 'https://ziyarathinfo.wordpress.com/2015/03/02/%e0%b4%87%e0%b4%ae%e0%b4%be%e0%b4%82-%e0%b4%a4%e0%b5%81%e0%b4%b0%e0%b5%8d%e2%80%8d%e0%b4%ae%e0%b5%81%e0%b4%a6%e0%b4%bf/', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO uroos (id, title, malayalam_title, maqam_id, is_standalone, resting_person, hijri_month, hijri_month_name, hijri_day, gregorian_date, recurrence, venue_name, city, state, country, description, history, significance, program_schedule, nercha_offerings, how_to_reach, organizer_name, organizer_contact, cover_image, source_url, created_from_request_id, status, created_at, updated_at) VALUES ('imam-ibn-hajar-al-haytami-uroos', 'Imam Ibn Hajar al-Haytami Commemoration', 'ഇമാം ഇബ്‌നു ഹജർ ഹൈതമി (റ) അനുസ്മരണം', NULL, 1, 'Shihabuddin Ahmad Ibn Hajar al-Haytami al-Makki (റ)', 7, 'റജബ് (Rajab)', 23, 'February (Annually)', 'Annual scholarly commemoration', 'Jannat al-Mu''alla Historical Cemetery', 'Makkah al-Mukarramah', 'Makkah Province', 'Saudi Arabia', 'Annual commemoration honoring the supreme Shafi''i legal authority and author of Tuhfat al-Muhtaj, revered by Islamic scholars across Kerala and the Muslim world.', 'Authored Tuhfat al-Muhtaj while teaching in the sacred precinct of Makkah; this text serves as the ultimate reference for fatwas in Malabar.', 'The intellectual link connecting Kerala''s traditional Dars system directly to classical Makkah scholarship.', '[{"time":"05:00 PM","event":"Fiqh & Fatawa Discourse","description":"Examining Ibn Hajar''s jurisprudential legacy."}]', 'Scholarly publications and Quran recitations.', '[{"mode":"By Air","details":"King Abdulaziz International Airport, Jeddah (JED) — 85 km."}]', 'Classical Shafi''i Fiqh Academy', 'info@shafii-academy.org', 'https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&q=80&w=1200', 'https://ziyarathinfo.wordpress.com/2015/03/04/%e0%b4%87%e0%b4%ae%e0%b4%be%e0%b4%82-%e0%b4%87%e0%b4%ac%e0%b5%8d%e2%80%8c%e0%b4%a8%e0%b5%81-%e0%b4%b9%e0%b4%9c%e0%b4%b0%e0%b5%8d%e2%80%8d-%e0%b4%b9%e0%b5%88%e0%b4%a4%e0%b4%ae%e0%b4%bf%e0%b4%b1/', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO uroos (id, title, malayalam_title, maqam_id, is_standalone, resting_person, hijri_month, hijri_month_name, hijri_day, gregorian_date, recurrence, venue_name, city, state, country, description, history, significance, program_schedule, nercha_offerings, how_to_reach, organizer_name, organizer_contact, cover_image, source_url, created_from_request_id, status, created_at, updated_at) VALUES ('imam-muslim-uroos', 'Imam Muslim ibn al-Hajjaj Commemoration', 'ഇമാം മുസ്‌ലിം (റ) ആണ്ട് അനുസ്മരണം', NULL, 1, 'Imam Abul Husayn Muslim ibn al-Hajjaj al-Naysaburi (റ)', 7, 'റജബ് (Rajab)', 25, 'February (Annually)', 'Annual commemoration on Rajab 25', 'Nishapur Historical Memorial', 'Nishapur', 'Razavi Khorasan', 'Iran', 'Spiritual commemoration honoring the compiler of Sahih Muslim, the second most authentic compendium of Hadith in Islamic civilization.', 'Dedicated his entire lifespan to establishing rigorous Hadith methodologies, chain validation (Isnad), and thematic arrangement.', 'Studied across all Islamic universities and recited in mosques for spiritual peace and barakah.', '[{"time":"09:30 AM","event":"Sahih Muslim Khatm Majlis","description":"Recitation of the concluding chapters of Sahih Muslim."}]', 'Hadith research grants and charitable feeding.', '[{"mode":"By Air","details":"Mashhad International Airport (MHD) — 110 km."}]', 'International Hadith Studies Institute', 'contact@hadith-studies.org', 'https://images.unsplash.com/photo-1591604129939-f1efa4d9f7fa?auto=format&fit=crop&q=80&w=1200', 'https://ziyarathinfo.wordpress.com/2015/03/02/%e0%b4%87%e0%b4%ae%e0%b4%be%e0%b4%82-%e0%b4%ae%e0%b5%81%e0%b4%b8%e0%b5%8d%e2%80%8c%e0%b4%b2%e0%b4%bf%e0%b4%82-%e0%b4%b1/', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO uroos (id, title, malayalam_title, maqam_id, is_standalone, resting_person, hijri_month, hijri_month_name, hijri_day, gregorian_date, recurrence, venue_name, city, state, country, description, history, significance, program_schedule, nercha_offerings, how_to_reach, organizer_name, organizer_contact, cover_image, source_url, created_from_request_id, status, created_at, updated_at) VALUES ('padinjarangadi-arakkal-mooppar-uroos', 'Arakkal Mooppar Kunji Marakkar Uroos', 'അറക്കൽ മൂപ്പർ കുഞ്ഞി മരക്കാർ (റ) പടിഞ്ഞാറങ്ങാടി നേർച്ച', NULL, 1, 'Arakkal Mooppar Kunji Marakkar (ഖ.സി)', 8, 'ശഅ്ബാൻ (Sha''ban)', 19, 'March (Annually)', 'Annual 3-day nercha concluding on Sha''ban 19', 'Padinjarangadi Dargah Sharif', 'Padinjarangadi, Palakkad', 'Kerala', 'India', 'Historic Uroos commemorating the brave warrior-saint Kunji Marakkar of the royal Arakkal lineage with communal unity, spiritual litanies, and festive harmony.', 'A respected leader and mystic who defended justice and assisted agrarian communities across the Palakkad and Malappuram borders.', 'A vibrant communal gathering celebrated with high reverence by all local communities.', '[{"time":"05:00 PM","event":"Kodiyettam","description":"Ceremonial flag raising."},{"time":"08:00 PM","event":"Mawlid & Dua","description":"Supplication assembly."}]', 'Traditional Neychoru distribution.', '[{"mode":"By Train","details":"Pattambi Railway Station — 14 km."}]', 'Padinjarangadi Dargah Committee', '+91 466 228 9011', 'https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&q=80&w=1200', 'https://ziyarathinfo.wordpress.com/2015/03/05/%e0%b4%85%e0%b4%b1%e0%b4%95%e0%b5%8d%e0%b4%95%e0%b4%b2%e0%b5%8d%e2%80%8d-%e0%b4%ae%e0%b5%82%e0%b4%aa%e0%b5%8d%e0%b4%aa%e0%b4%b0%e0%b5%8d%e2%80%8d-%e0%b4%95%e0%b5%81%e0%b4%9e%e0%b5%8d%e0%b4%9e/', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO uroos (id, title, malayalam_title, maqam_id, is_standalone, resting_person, hijri_month, hijri_month_name, hijri_day, gregorian_date, recurrence, venue_name, city, state, country, description, history, significance, program_schedule, nercha_offerings, how_to_reach, organizer_name, organizer_contact, cover_image, source_url, created_from_request_id, status, created_at, updated_at) VALUES ('tiruchirappalli-nathahar-badshah-uroos', 'Hazrat Tabre Alam Nathahar Badshah Uroos', 'ഹസ്‌റത്ത് നഥ്ഹർ ബാദ്ശാഹ് ആണ്ട്, തിരുച്ചിറപ്പള്ളി', NULL, 1, 'Sultan Syed Babayya Nathahar Vali Badshah (റ)', 9, 'റമളാൻ (Ramadan)', 14, 'March / April (Annually)', 'Annual commemoration on Ramadan 14', 'Hazrat Nathahar Vali Dargah Complex', 'Tiruchirappalli', 'Tamil Nadu', 'India', 'A grand annual gathering in Trichy commemorating the royal prince-turned-Sufi master Babayya Nathahar Badshah, revered across South India for spiritual benevolence.', 'Gave up his kingdom in the Middle East to wander as an ascetic seeker, eventually settling in Tiruchirappalli over a thousand years ago.', 'A sacred convergence of pilgrims from Tamil Nadu, Kerala, Karnataka, and Sri Lanka.', '[{"time":"05:00 PM","event":"Grand Iftar Majlis","description":"Mass fast-breaking gathering for tens of thousands."},{"time":"09:30 PM","event":"Taraweeh & Tahajjud Majlis","description":"Night prayer and spiritual supplications."}]', 'Special Ramadan Iftar feast, dates, and porridge distribution.', '[{"mode":"By Train","details":"Tiruchirappalli Junction (TPJ) — 4 km."},{"mode":"By Air","details":"Tiruchirappalli International Airport (TRZ) — 8 km."}]', 'Hazrat Nathahar Vali Dargah Trust', '+91 431 270 1200', 'https://images.unsplash.com/photo-1564769625905-50e93615e769?auto=format&fit=crop&q=80&w=1200', 'https://ziyarathinfo.wordpress.com/2015/03/02/%e0%b4%b9%e0%b4%b8%e0%b5%8d%e2%80%8c%e0%b4%b1%e0%b4%a4%e0%b5%8d%e0%b4%a4%e0%b5%8d%e2%80%8c-%e0%b4%a8%e0%b4%a5%e0%b5%8d%e0%b4%b9%e0%b4%b0%e0%b5%8d%e2%80%8d-%e0%b4%ac%e0%b4%be%e0%b4%a6%e0%b5%8d%e0%b4%b6/', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO uroos (id, title, malayalam_title, maqam_id, is_standalone, resting_person, hijri_month, hijri_month_name, hijri_day, gregorian_date, recurrence, venue_name, city, state, country, description, history, significance, program_schedule, nercha_offerings, how_to_reach, organizer_name, organizer_contact, cover_image, source_url, created_from_request_id, status, created_at, updated_at) VALUES ('imam-bukhari-uroos', 'Amir al-Mu''minin Imam al-Bukhari Commemoration', 'ഇമാം ബുഖാരി (റ) ആണ്ട് അനുസ്മരണം', NULL, 1, 'Imam Muhammad ibn Ismail al-Bukhari (റ)', 10, 'ശവ്വാൽ (Shawwal)', 1, 'April / May (Annually on Eid al-Fitr)', 'Annual worldwide commemoration on Eid al-Fitr', 'Imam al-Bukhari Memorial Complex', 'Hartang, Samarkand', 'Samarkand Region', 'Uzbekistan', 'Global celebration commemorating the undisputed leader of Hadith scholars, author of Sahih al-Bukhari, on the blessed night of Eid al-Fitr when he passed into divine mercy.', 'Spent 16 years compiling his Sahih out of 600,000 traditions, performing two rak''ahs of prayer and ghusl before inscribing each single Hadith.', 'Sahih al-Bukhari is accepted across all Muslim schools as the most authentic text after the Holy Qur''an.', '[{"time":"09:00 AM","event":"Khatm al-Bukhari Assembly","description":"Global broadcast and completion recitation of the Sahih."}]', 'Scholarly endowments, Qur''an and Hadith manuscript distributions.', '[{"mode":"By Air","details":"Samarkand International Airport (SKD) — 25 km."}]', 'Imam al-Bukhari International Scientific Research Center', 'info@bukhari.uz', 'https://images.unsplash.com/photo-1591604129939-f1efa4d9f7fa?auto=format&fit=crop&q=80&w=1200', 'https://ziyarathinfo.wordpress.com/2015/02/23/%e0%b4%87%e0%b4%ae%e0%b4%be%e0%b4%82-%e0%b4%ac%e0%b5%81%e0%b4%96%e0%b4%be%e0%b4%b0%e0%b4%bf%e0%b4%b1/', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO uroos (id, title, malayalam_title, maqam_id, is_standalone, resting_person, hijri_month, hijri_month_name, hijri_day, gregorian_date, recurrence, venue_name, city, state, country, description, history, significance, program_schedule, nercha_offerings, how_to_reach, organizer_name, organizer_contact, cover_image, source_url, created_from_request_id, status, created_at, updated_at) VALUES ('imam-abu-dawud-uroos', 'Imam Abu Dawud as-Sijistani Commemoration', 'ഇമാം അബൂദാവൂദ് (റ) അനുസ്മരണം', NULL, 1, 'Imam Sulayman ibn al-Ash''ath Abu Dawud (റ)', 10, 'ശവ്വാൽ (Shawwal)', 16, 'May (Annually)', 'Annual scholarly commemoration', 'Basra Historical Scholar Precinct', 'Basra', 'Basra Governorate', 'Iraq', 'Honoring the legendary Hadith jurist and compiler of Sunan Abi Dawud, revered for ethical jurisprudence, piety, and compiling the fundamental legal Sunnahs.', 'Praised by Imam Ahmad ibn Hanbal as a master of legal traditions and guardian of prophetic morality.', 'The definitive manual of Ahkam (legal rulings) for students of Islamic jurisprudence worldwide.', '[{"time":"10:00 AM","event":"Sunan Abu Dawud Symposium","description":"Analytical readings from the Sunan."}]', 'Academic publication endowments and charity.', '[{"mode":"By Air","details":"Basra International Airport (BSR) — 15 km."}]', 'Classical Hadith Heritage Society of Iraq', 'contact@iraq-hadith.iq', 'https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&q=80&w=1200', 'https://ziyarathinfo.wordpress.com/2015/03/02/%e0%b4%87%e0%b4%ae%e0%b4%be%e0%b4%82-%e0%b4%85%e0%b4%ac%e0%b5%82%e0%b4%a6%e0%b4%be%e0%b4%b5%e0%b5%82%e0%b4%a6%e0%b5%8d-%e0%b4%ae%e0%b4%96%e0%b4%be%e0%b4%82-%e0%b4%ac%e0%b4%b8%e0%b5%8d%e0%b4%b5/', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO uroos (id, title, malayalam_title, maqam_id, is_standalone, resting_person, hijri_month, hijri_month_name, hijri_day, gregorian_date, recurrence, venue_name, city, state, country, description, history, significance, program_schedule, nercha_offerings, how_to_reach, organizer_name, organizer_contact, cover_image, source_url, created_from_request_id, status, created_at, updated_at) VALUES ('tanur-abdurahman-shaikh-uroos', 'Tanur Abdurahman Shaikh Uroos', 'താനൂർ അബ്ദുർറഹ്മാൻ ശൈഖ് (റ) നേർച്ച', NULL, 1, 'Qutb Sayyid Abdurahman Shaikh (റ)', 10, 'ശവ്വാൽ (Shawwal)', 22, 'May (Annually)', 'Annual 3-day coastal nercha concluding on Shawwal 22', 'Tanur Valiya Kulangara Juma Masjid & Dargah', 'Tanur, Malappuram', 'Kerala', 'India', 'A historical coastal nercha in Tanur celebrating the legacy of Sayyid Abdurahman Shaikh with seafaring traditions, prayers, and community distribution.', 'The shrine has blessed the fishermen and coastal traders of Tanur for centuries, serving as a beacon of safety and moral guidance.', 'A beloved festival characterized by colorful coastal processions, Mawlid recitations, and community solidarity.', '[{"time":"05:00 PM","event":"Kodiyettam","description":"Flag hoisting by coastal elders."},{"time":"07:30 PM","event":"Mawlid Majlis","description":"Praise of the holy Prophet."},{"time":"Final Day","event":"Neychoru Distribution","description":"Mass distribution of food to all."}]', 'Special coastal Neychoru.', '[{"mode":"By Train","details":"Tanur Railway Station (TA) — 2 km."},{"mode":"By Road","details":"Located directly on the coastal highway between Parappanangadi and Tirur."}]', 'Tanur Valiya Kulangara Dargah Committee', '+91 494 258 2002', 'https://images.unsplash.com/photo-1564769625905-50e93615e769?auto=format&fit=crop&q=80&w=1200', 'https://ziyarathinfo.wordpress.com/2015/03/05/%e0%b4%85%e0%b4%ac%e0%b4%a6%e0%b5%81%e0%b4%b0%e0%b5%8d%e2%80%8d%e0%b4%b1%e0%b4%b9%e0%b5%8d%e0%b4%ae%e0%b4%be%e0%b4%a8%e0%b5%8d%e2%80%8d-%e0%b4%b6%e0%b5%88%e0%b4%96%e0%b5%8d-%e0%b4%b1-%e0%b4%ae/', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO uroos (id, title, malayalam_title, maqam_id, is_standalone, resting_person, hijri_month, hijri_month_name, hijri_day, gregorian_date, recurrence, venue_name, city, state, country, description, history, significance, program_schedule, nercha_offerings, how_to_reach, organizer_name, organizer_contact, cover_image, source_url, created_from_request_id, status, created_at, updated_at) VALUES ('sayyid-jifri-kozhikode-uroos', 'Sayyid Shaikh Jifri Kozhikode Uroos', 'സയ്യിദ് ശൈഖ് ജിഫ്‌രി (റ) ആണ്ട് നേർച്ച, കോഴിക്കോട്', NULL, 1, 'Qutbuz Zaman Sayyid Shaikh Jifri Ba''alawi (റ)', 11, 'ദുൽഖഅ്ദ് (Dhu al-Qi''dah)', 8, 'May / June (Annually)', 'Annual commemoration on Dhu al-Qi''dah 8', 'Jifri House & Dargah, Kuttichira', 'Kozhikode', 'Kerala', 'India', 'Prestigious annual gathering commemorating the grand Ba''alawi patriarch of Malabar, Sayyid Shaikh Jifri, who was welcomed with royal honors by the Zamorin of Calicut in 1746.', 'Arrived from Hadhramaut in 1746 and became the paramount spiritual guide in Malabar. The Zamorin granted him tax-free lands in Kuttichira where his shrine stands today.', 'A cornerstone of Kerala''s Ba''alawi spiritual heritage, celebrated with Ratheeb recitations, scholarly assemblies, and community unity.', '[{"time":"05:00 PM","event":"Kuttichira Ziyarath","description":"Solemn opening prayers at the Jifri Dargah."},{"time":"07:30 PM","event":"Ratheeb al-Haddad","description":"Litanies of remembrance and prophetic praise."},{"time":"09:30 PM","event":"Tabarruk Distribution","description":"Sacred feast served to attendees."}]', 'Sacred Neychoru, sweets, and educational scholarships.', '[{"mode":"By Train","details":"Kozhikode Main Railway Station (CLT) — 2 km."},{"mode":"By Air","details":"Calicut International Airport — 28 km."}]', 'Sayyid Jifri Memorial Trust, Kuttichira', '+91 495 272 0555', 'https://images.unsplash.com/photo-1591604129939-f1efa4d9f7fa?auto=format&fit=crop&q=80&w=1200', 'https://ziyarathinfo.wordpress.com/2015/03/05/%e0%b4%b8%e0%b4%af%e0%b5%8d%e0%b4%af%e0%b4%bf%e0%b4%a6%e0%b5%8d-%e0%b4%b6%e0%b5%88%e0%b4%96%e0%b5%8d-%e0%b4%9c%e0%b4%bf%e0%b4%ab%e0%b5%8d%e2%80%8c%e0%b4%b0%e0%b4%bf-%e0%b4%b1-%e0%b4%95%e0%b5%8b/', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO uroos (id, title, malayalam_title, maqam_id, is_standalone, resting_person, hijri_month, hijri_month_name, hijri_day, gregorian_date, recurrence, venue_name, city, state, country, description, history, significance, program_schedule, nercha_offerings, how_to_reach, organizer_name, organizer_contact, cover_image, source_url, created_from_request_id, status, created_at, updated_at) VALUES ('edappal-shaikh-sirajuddin-uroos', 'Shaikh Sirajuddin Ailakkad Uroos', 'ശൈഖ് സിറാജുദ്ദീൻ (റ) ഐലക്കാട് ആണ്ട് നേർച്ച', NULL, 1, 'Shaikh Sirajuddin Valiyullah (റ)', 12, 'ദുൽഹിജ്ജ (Dhu al-Hijjah)', 12, 'June / July (Annually)', 'Annual commemoration on Dhu al-Hijjah 12', 'Ailakkad Juma Masjid & Dargah', 'Ailakkad, Edappal, Malappuram', 'Kerala', 'India', 'Annual commemoration honoring Shaikh Sirajuddin in Ailakkad, featuring Quranic recitation gatherings and community annadanam.', 'A saint of great piety whose teachings inspired rural farming communities of Edappal toward devotion and social harmony.', 'A serene village festival drawing pilgrims across Malappuram and Thrissur districts.', '[{"time":"05:00 PM","event":"Dua & Ziyarath","description":"Opening prayers."},{"time":"07:30 PM","event":"Annadanam","description":"Communal distribution of blessed food."}]', 'Neychoru and sweets.', '[{"mode":"By Train","details":"Kuttippuram Station — 12 km."},{"mode":"By Road","details":"Located on the Edappal-Ponnani highway."}]', 'Ailakkad Dargah Committee', '+91 494 268 3344', 'https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&q=80&w=1200', 'https://ziyarathinfo.wordpress.com/2015/03/05/%e0%b4%b6%e0%b5%88%e0%b4%96%e0%b5%8d%e2%80%8c-%e0%b4%b8%e0%b4%bf%e0%b4%b1%e0%b4%be%e0%b4%9c%e0%b5%81%e0%b4%a6%e0%b5%8d%e0%b4%a6%e0%b5%80%e0%b4%a8%e0%b5%8d%e2%80%8d%e0%b4%b1-%e0%b4%90%e0%b4%b2/', NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO uroos (id, title, malayalam_title, maqam_id, is_standalone, resting_person, hijri_month, hijri_month_name, hijri_day, gregorian_date, recurrence, venue_name, city, state, country, description, history, significance, program_schedule, nercha_offerings, how_to_reach, organizer_name, organizer_contact, cover_image, source_url, created_from_request_id, status, created_at, updated_at) VALUES ('peringathur-uroos', 'Peringathur Valiya Uroos Mubarak', 'പെരിങ്ങത്തൂർ വലിയ ഉറൂസ്', NULL, 1, 'Sayyid Zainul Abideen Thangal (Peringathur)', 5, 'ജമാദുൽ അവ്വൽ (Jumada al-Awwal)', 14, 'November (Annually)', 'Annual 5-day cultural and religious gathering', 'Peringathur Grand Dargah Ground', 'Peringathur, Kannur District', 'Kerala', 'India', 'A renowned standalone Uroos festival in North Malabar attracting thousands of spiritual seekers with educational exhibitions, mass Mawlid recitations, and humanitarian aid drives.', 'Dedicated to the memory of Sayyid Zainul Abideen Thangal who dedicated his life to community education, peaceful dispute resolution, and welfare of coastal communities in Kannur and Kozhikode borders.', 'An essential standalone spiritual landmark on the northern border of Malabar, known for widespread community hospitality and cultural unity.', '[{"time":"Day 1 - 05:00 PM","event":"Grand Flag Hoisting Ceremony","description":"Opening session led by regional Sadath and Ulama."},{"time":"Day 2 to 4 - 07:30 PM","event":"Theme Lectures & Moral Studies","description":"Discourses on youth, community values, and Islamic ethics."},{"time":"Final Night - 09:00 PM","event":"Khatm al-Quran & Mega Dua","description":"Solemn prayer gathering concluding with traditional tabarruk feast."}]', 'Sweet Neyappam, rice distribution to poor households, and educational aid.', '[{"mode":"By Air","details":"Kannur International Airport (CNN) — 28 km away."},{"mode":"By Train","details":"Thalassery Railway Station — 16 km; Vadakara — 14 km."},{"mode":"By Road","details":"Easily reachable from Thalassery-Kozhikode road via Peringathur bridge."}]', 'Peringathur Uroos Advisory Council', '+91 490 238 4110', 'https://images.unsplash.com/photo-1564769625905-50e93615e769?auto=format&fit=crop&q=80&w=1200', NULL, NULL, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z');
